-- Generated by matugen for Hush. A base16-driven colorscheme with Material surfaces.
local c = {
  bg = "{{colors.surface.default.hex}}", bg1 = "{{colors.surface_container.default.hex}}",
  bg2 = "{{colors.surface_container_high.default.hex}}", bg3 = "{{colors.surface_container_highest.default.hex}}",
  fg = "{{colors.on_surface.default.hex}}", fg_dim = "{{colors.on_surface_variant.default.hex}}",
  outline = "{{colors.outline.default.hex}}", outline_v = "{{colors.outline_variant.default.hex}}",
  primary = "{{colors.primary.default.hex}}", on_primary = "{{colors.on_primary.default.hex}}",
  secondary = "{{colors.secondary.default.hex}}", tertiary = "{{colors.tertiary.default.hex}}",
  error = "{{colors.error.default.hex}}",
  b08 = "{{base16.base08.default.hex}}", b09 = "{{base16.base09.default.hex}}", b0a = "{{base16.base0a.default.hex}}",
  b0b = "{{base16.base0b.default.hex}}", b0c = "{{base16.base0c.default.hex}}", b0d = "{{base16.base0d.default.hex}}",
  b0e = "{{base16.base0e.default.hex}}", b0f = "{{base16.base0f.default.hex}}",
}
vim.cmd("highlight clear")
if vim.fn.exists("syntax_on") == 1 then vim.cmd("syntax reset") end
vim.o.termguicolors = true
vim.o.background = "{{mode}}"
vim.g.colors_name = "hush"
local hi = function(g, o) vim.api.nvim_set_hl(0, g, o) end
-- UI
hi("Normal", { fg = c.fg, bg = "NONE" })
hi("NormalFloat", { fg = c.fg, bg = c.bg1 })
hi("FloatBorder", { fg = c.outline_v, bg = c.bg1 })
hi("NormalNC", { fg = c.fg_dim, bg = "NONE" })
hi("LineNr", { fg = c.outline })
hi("CursorLineNr", { fg = c.primary, bold = true })
hi("CursorLine", { bg = c.bg1 })
hi("ColorColumn", { bg = c.bg1 })
hi("SignColumn", { bg = "NONE" })
hi("VertSplit", { fg = c.outline_v })
hi("WinSeparator", { fg = c.outline_v })
hi("StatusLine", { fg = c.fg, bg = c.bg1 })
hi("StatusLineNC", { fg = c.fg_dim, bg = c.bg })
hi("TabLine", { fg = c.fg_dim, bg = c.bg1 })
hi("TabLineSel", { fg = c.on_primary, bg = c.primary })
hi("TabLineFill", { bg = c.bg })
hi("Pmenu", { fg = c.fg, bg = c.bg1 })
hi("PmenuSel", { fg = c.on_primary, bg = c.primary })
hi("PmenuSbar", { bg = c.bg2 })
hi("PmenuThumb", { bg = c.outline })
hi("Visual", { bg = c.bg3 })
hi("Search", { fg = c.on_primary, bg = c.secondary })
hi("IncSearch", { fg = c.on_primary, bg = c.primary })
hi("CurSearch", { fg = c.on_primary, bg = c.primary })
hi("MatchParen", { fg = c.primary, bold = true, underline = true })
hi("Cursor", { fg = c.on_primary, bg = c.primary })
hi("NonText", { fg = c.outline_v })
hi("Whitespace", { fg = c.outline_v })
hi("EndOfBuffer", { fg = c.bg })
hi("Folded", { fg = c.fg_dim, bg = c.bg1 })
hi("FoldColumn", { fg = c.outline })
hi("Directory", { fg = c.primary })
hi("Title", { fg = c.primary, bold = true })
hi("Question", { fg = c.tertiary })
hi("MoreMsg", { fg = c.tertiary })
hi("ErrorMsg", { fg = c.error })
hi("WarningMsg", { fg = c.b0a })
hi("DiffAdd", { bg = c.bg1, fg = c.b0b })
hi("DiffChange", { bg = c.bg1, fg = c.b0a })
hi("DiffDelete", { bg = c.bg1, fg = c.b08 })
hi("DiffText", { bg = c.bg2, fg = c.b0d })
-- Syntax
hi("Comment", { fg = c.outline, italic = true })
hi("Constant", { fg = c.b09 })
hi("String", { fg = c.b0b })
hi("Character", { fg = c.b0b })
hi("Number", { fg = c.b09 })
hi("Boolean", { fg = c.b09 })
hi("Float", { fg = c.b09 })
hi("Identifier", { fg = c.fg })
hi("Function", { fg = c.b0d })
hi("Statement", { fg = c.b0e })
hi("Conditional", { fg = c.b0e })
hi("Repeat", { fg = c.b0e })
hi("Label", { fg = c.b0e })
hi("Operator", { fg = c.fg_dim })
hi("Keyword", { fg = c.b0e })
hi("Exception", { fg = c.b08 })
hi("PreProc", { fg = c.b0c })
hi("Include", { fg = c.b0c })
hi("Define", { fg = c.b0e })
hi("Macro", { fg = c.b0c })
hi("Type", { fg = c.b0a })
hi("StorageClass", { fg = c.b0a })
hi("Structure", { fg = c.b0a })
hi("Typedef", { fg = c.b0a })
hi("Special", { fg = c.b0c })
hi("SpecialChar", { fg = c.b0f })
hi("Tag", { fg = c.b0d })
hi("Delimiter", { fg = c.fg_dim })
hi("SpecialComment", { fg = c.outline, italic = true })
hi("Debug", { fg = c.b08 })
hi("Underlined", { underline = true })
hi("Error", { fg = c.error })
hi("Todo", { fg = c.on_primary, bg = c.primary, bold = true })
-- Treesitter and LSP links
for group, target in pairs({
  ["@variable"] = "Identifier", ["@variable.builtin"] = "Special", ["@variable.parameter"] = "Identifier",
  ["@variable.member"] = "Identifier", ["@constant"] = "Constant", ["@constant.builtin"] = "Constant",
  ["@module"] = "Type", ["@string"] = "String", ["@string.escape"] = "SpecialChar", ["@character"] = "Character",
  ["@number"] = "Number", ["@boolean"] = "Boolean", ["@function"] = "Function", ["@function.builtin"] = "Function",
  ["@function.call"] = "Function", ["@function.method"] = "Function", ["@constructor"] = "Type",
  ["@keyword"] = "Keyword", ["@keyword.function"] = "Keyword", ["@keyword.return"] = "Keyword",
  ["@keyword.operator"] = "Operator", ["@operator"] = "Operator", ["@punctuation.delimiter"] = "Delimiter",
  ["@punctuation.bracket"] = "Delimiter", ["@type"] = "Type", ["@type.builtin"] = "Type", ["@property"] = "Identifier",
  ["@attribute"] = "PreProc", ["@comment"] = "Comment", ["@tag"] = "Tag", ["@tag.attribute"] = "Identifier",
  ["@markup.heading"] = "Title", ["@markup.link"] = "Underlined", ["@markup.raw"] = "String",
  ["DiagnosticError"] = "Error", ["DiagnosticWarn"] = "WarningMsg", ["DiagnosticInfo"] = "Question", ["DiagnosticHint"] = "Comment",
  ["LspReferenceText"] = "Visual", ["LspReferenceRead"] = "Visual", ["LspReferenceWrite"] = "Visual",
  ["TelescopeBorder"] = "FloatBorder", ["TelescopeSelection"] = "PmenuSel", ["NeoTreeNormal"] = "Normal",
  ["NeoTreeNormalNC"] = "NormalNC", ["NeoTreeDirectoryName"] = "Directory", ["NeoTreeDirectoryIcon"] = "Directory",
  ["SnacksDashboardHeader"] = "Title", ["SnacksDashboardKey"] = "Function", ["SnacksDashboardDesc"] = "Identifier",
  ["BufferLineFill"] = "TabLineFill", ["WhichKeyBorder"] = "FloatBorder", ["NotifyBackground"] = "NormalFloat",
}) do hi(group, { link = target }) end
hi("DiagnosticUnderlineError", { undercurl = true, sp = c.error })
hi("DiagnosticUnderlineWarn", { undercurl = true, sp = c.b0a })
hi("GitSignsAdd", { fg = c.b0b })
hi("GitSignsChange", { fg = c.b0a })
hi("GitSignsDelete", { fg = c.b08 })
hi("IndentBlanklineChar", { fg = c.outline_v })
